const body = $input.first().json.body || $input.first().json;

const keyword = body.keyword || '';
const niche = body.niche || keyword;
const countries = body.countries || ['CO'];
const country = countries[0] || 'CO';
const max_ads = body.max_ads || 20;
const dna_expert = body.dna_expert || '';
const dna_audience = body.dna_audience || '';
const dna_product = body.dna_product || '';
const telegram_chat_id = body.telegram_chat_id || '';
const email = body.email || '';

const REFERENTES = [
  'Melisa Escobar', 'Tata Salazar', 'Kale Anders',
  'Leandro Ladeira', 'Michell Edery', 'Mike Munzvil'
];

const fbUrl = `https://www.facebook.com/ads/library/?active_status=active&ad_type=all&country=${country}&q=${encodeURIComponent(keyword)}&search_type=keyword_unordered&media_type=all`;

return [{
  json: {
    keyword, niche, country, max_ads,
    dna_expert, dna_audience, dna_product,
    telegram_chat_id, email, REFERENTES,
    fbActorInput: {
      urls: [{ url: fbUrl }],
      count: Math.min(max_ads * 2, 50),
      "scrapePageAds.activeStatus": "active",
      "scrapePageAds.countryCode": country
    },
    tiktokActorInput: {
      searchQueries: [keyword],
      resultsPerPage: Math.min(max_ads * 2, 50),
      shouldDownloadCovers: false,
      shouldDownloadVideos: false
    }
  }
}];

const items = $input.all().map(i => i.json);
const config = $('Preparar Variables').first().json;
const REFERENTES = config.REFERENTES;
const max_ads = config.max_ads;

const now = Date.now();
const THREE_MONTHS_MS = 90 * 24 * 60 * 60 * 1000;
const FIFTEEN_DAYS_MS = 15 * 24 * 60 * 60 * 1000;

const winners = [];

for (const ad of items) {
  const isTikTok = !!(ad.videoUrl || ad.webVideoUrl || ad.diggCount !== undefined || ad.playCount !== undefined);
  const isFacebook = !!(ad.adArchiveID || ad.body || ad.pageName || ad.startDate);

  if (isTikTok) {
    const views = ad.playCount || ad.plays || 0;
    const createTime = ad.createTimeISO
      ? new Date(ad.createTimeISO).getTime()
      : (ad.createTime ? ad.createTime * 1000 : 0);
    const ageMs = now - createTime;

    if (views >= 100000 && ageMs <= THREE_MONTHS_MS && createTime > 0) {
      winners.push({
        source: 'tiktok',
        link: ad.webVideoUrl || `https://www.tiktok.com/@${ad.authorMeta?.name || 'unknown'}/video/${ad.id}`,
        author: ad.authorMeta?.nickName || ad.authorMeta?.name || 'Desconocido',
        text: ad.text || '',
        views,
        likes: ad.diggCount || ad.likes || 0,
        days_old: Math.floor(ageMs / 86400000),
        is_referent: REFERENTES.some(r => (ad.authorMeta?.nickName || '').toLowerCase().includes(r.toLowerCase())),
      });
    }
  } else if (isFacebook) {
    const adText = ad.body || (ad.adCreativeBodies && ad.adCreativeBodies[0]) || '';
    const startTime = ad.startDate || ad.adDeliveryStartTime || '';
    const startMs = startTime ? new Date(startTime).getTime() : 0;
    const daysRunning = startMs ? Math.floor((now - startMs) / 86400000) : 0;
    const pageName = ad.pageName || ad.page_name || '';
    const isReferent = REFERENTES.some(r => pageName.toLowerCase().includes(r.toLowerCase()));

    if ((daysRunning >= 15 || isReferent) && adText.length > 30) {
      winners.push({
        source: 'facebook',
        link: ad.adSnapshotUrl || ad.url || `https://www.facebook.com/ads/library/?id=${ad.adArchiveID || ad.id || ''}`,
        author: pageName,
        text: adText,
        headline: ad.title || '',
        cta: ad.ctaText || '',
        days_running: daysRunning,
        is_referent: isReferent,
      });
    }
  }
}

winners.sort((a, b) => {
  if (a.is_referent !== b.is_referent) return b.is_referent ? 1 : -1;
  if (a.source === 'tiktok' && b.source === 'tiktok') return (b.views || 0) - (a.views || 0);
  return (b.days_running || 0) - (a.days_running || 0);
});

const selected = winners.slice(0, max_ads);

return [{ json: { winners: selected, total: selected.length, config } }];

const data = $input.first().json;
const winners = data.winners;
const config = data.config;

const adsText = winners.map((w, i) => {
  let desc = `--- ANUNCIO ${i+1} ---`;
  desc += `
Fuente: ${w.source}`;
  desc += `
Link: ${w.link}`;
  desc += `
Autor: ${w.author}`;
  if (w.is_referent) desc += `
⭐ REFERENTE CONOCIDO`;
  desc += `
Texto: ${w.text}`;
  if (w.headline) desc += `
Headline: ${w.headline}`;
  if (w.cta) desc += `
CTA: ${w.cta}`;
  if (w.days_running) desc += `
Dias corriendo: ${w.days_running}`;
  if (w.views) desc += `
Views: ${w.views.toLocaleString()}`;
  return desc;
}).join('

');

const requestBody = {
  model: 'claude-sonnet-4-6-20250514',
  max_tokens: 8000,
  system: `Eres un experto en copywriting publicitario. Tu trabajo es analizar anuncios ganadores y reescribirlos adaptandolos al DNA del experto.

DNA del Experto (personalidad/voz):
${config.dna_expert}

DNA de Audiencia (cliente ideal):
${config.dna_audience}

DNA de Producto (oferta):
${config.dna_product}

INSTRUCCIONES:
1. Para cada anuncio de referencia, manten el link original como REFERENTE
2. Analiza la estructura persuasiva (hook, cuerpo, CTA)
3. Reescribe COMPLETAMENTE con la voz/personalidad del experto
4. Adapta al producto y audiencia del DNA
5. Formato EXACTO por cada contenido:

CONTENIDO #N
REFERENTE: [link del anuncio original]
PLATAFORMA: [facebook/tiktok]
HOOK 1: [gancho principal reescrito]
HOOK 2: [gancho alternativo reescrito]
CUERPO: [cuerpo del anuncio adaptado]
CTA 1: [llamada a la accion principal]
CTA 2: [llamada a la accion alternativa]

---

Responde SOLO con los contenidos formateados.`,
  messages: [{
    role: 'user',
    content: `Analiza y adapta estos ${data.total} anuncios ganadores:

${adsText}`
  }]
};

return [{ json: { requestBody, config, total: data.total } }];

const response = $input.first().json;
const config = $('Preparar Request Claude').first().json.config;
const total = $('Preparar Request Claude').first().json.total;

const scripts = response.content?.[0]?.text || 'Error: no se generaron scripts';

const telegramMsg = `🎯 *Hooq Agente de Anuncios*\n\n` +
  `Nicho: *${config.keyword}*\n` +
  `Anuncios adaptados: *${total}*\n` +
  `Plataformas: FB Ads + TikTok\n\n` +
  `📋 *Scripts generados:*\n\n` +
  scripts.substring(0, 3800);

const emailHtml = `<h2>🎯 Hooq - Agente de Anuncios</h2>` +
  `<p><strong>Nicho:</strong> ${config.keyword}</p>` +
  `<p><strong>Anuncios adaptados:</strong> ${total}</p><hr>` +
  `<pre style="white-space:pre-wrap;font-family:monospace;font-size:14px;">${scripts}</pre>`;

return [{
  json: {
    scripts, telegramMsg, emailHtml,
    telegram_chat_id: config.telegram_chat_id,
    email: config.email,
    keyword: config.keyword, total
  }
}];
